$ErrorActionPreference='Continue';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path $ScriptDir 'lib/common.ps1');$pass=0;$fail=0;$results=@()
function Check-Tool{param($Name,$Req,$Command,$Args,$Min);if(-not(Test-Command $Command)){$script:results+=[pscustomobject]@{Tool=$Name;Req=$Req;Result='FAIL (no instalado)'};$script:fail++;return};try{$raw=& $Command $Args 2>$null|Select-Object -First 1;$v=Get-Version $raw}catch{$v=''};if(-not $v){$script:results+=[pscustomobject]@{Tool=$Name;Req=$Req;Result='FAIL (versión no detectable)'};$script:fail++;return};if($Min -and -not(Test-VersionGE $v $Min)){$script:results+=[pscustomobject]@{Tool=$Name;Req=$Req;Result="FAIL ($v < $Min)"};$script:fail++;return};$script:results+=[pscustomobject]@{Tool=$Name;Req=$Req;Result="PASS ($v)"};$script:pass++}
Check-Tool dotnet '>= 8.0.100' dotnet '--version' 8.0.100;Check-Tool python '>= 3.12.0' python '--version' 3.12.0;Check-Tool node '>= 20.0.0' node '--version' 20.0.0;Check-Tool pnpm '>= 9.0.0' pnpm '--version' 9.0.0;Check-Tool cmake '>= 3.28.0' cmake '--version' 3.28.0;Check-Tool ninja '>= 1.11.0' ninja '--version' 1.11.0;Check-Tool pio '>= 6.1.0' pio '--version' 6.1.0;Check-Tool terraform '>= 1.7.0' terraform 'version' 1.7.0;Check-Tool buf '>= 1.30.0' buf '--version' 1.30.0;Check-Tool git '>= 2.30.0' git '--version' 2.30.0
if(Test-Command docker){try{& docker info *>$null;$results+=[pscustomobject]@{Tool='docker';Req='daemon';Result="PASS ($(Get-Version (& docker --version)))"};$pass++}catch{$results+=[pscustomobject]@{Tool='docker';Req='daemon';Result='WARN (daemon no corre)'}}}else{$results+=[pscustomobject]@{Tool='docker';Req='daemon';Result='FAIL (no instalado)'};$fail++}
Write-Host '';Write-Host 'Conjunto Inteligente · Verificación del host (Windows)';$results|Format-Table -AutoSize;Write-Host "PASS: $pass   FAIL: $fail";if($fail -gt 0){exit 1};exit 0
